from pathlib import Path
import shutil,json
ROOT=Path(__file__).resolve().parent.parent
APPS=[('hifz-planner','Quran Memorization Workload Calculator','Plan new memorization alongside a growing revision workload.','teal'),('is-it-in-the-quran','Is This Actually in the Quran?','Check wording against the Arabic Quran and Pickthall translation.','blue'),('quran-concept-atlas','Quran Concept Atlas','Follow connected themes through carefully cited Quran passages.','teal'),('quran-escape-room','The Islamic Knowledge Escape Room','Read the evidence. Solve four locks. Open a new route through the Quran.','violet'),('stories-of-the-prophets','Stories of the Prophets Explorer','Explore selected Quran passages about 25 named prophets.','blue')]
seed=ROOT/'apps/ayah-threads'
for i,(slug,name,description,accent) in enumerate(APPS):
 app=ROOT/'apps'/slug
 for d in ['src/pages','src/layouts','src/lib','src/data','src/styles','tests','public/fonts']:(app/d).mkdir(parents=True,exist_ok=True)
 for f in ['astro.config.mjs','tsconfig.json','LICENSE','public/favicon.svg','public/_headers','public/robots.txt','src/pages/privacy.astro','src/pages/404.astro','src/layouts/Shell.astro','src/lib/utils.ts','src/lib/shell.ts','src/styles/global.css','tests/storage.test.ts']:
  shutil.copyfile(seed/f,app/f)
 for f in (seed/'public/fonts').iterdir():shutil.copyfile(f,app/'public/fonts'/f.name)
 package=json.loads((seed/'package.json').read_text());package['name']=slug
 for key in ['dev','preview']:package['scripts'][key]=package['scripts'][key].replace('4322',str(4326+i))
 (app/'package.json').write_text(json.dumps(package,indent=2)+'\n')
 (app/'src/data/config.json').write_text(json.dumps(dict(slug=slug,name=name,description=description,accent=accent,port=4326+i),indent=2))
 (app/'src/pages/sources.astro').write_text('''---
import Shell from '../layouts/Shell.astro';
import sources from '../data/sources.json';
import provenance from '../data/provenance.json';
---
<Shell title="Sources & methodology" active="sources"><article class="prose"><span class="eyebrow">Read the original</span><h1>Sources & methodology</h1><p>Canonical text and metadata were retrieved using <a href="https://mcp.quran.ai">Quran Foundation’s official Quran MCP</a>. They are bundled with the app so reading and searching need no live API.</p><h2>Text and interpretation</h2><p>Arabic: Uthmani Hafs (<code>ar-uthmani-hafs</code>). English: Marmaduke Pickthall (<code>en-pickthall</code>), whose historical public-domain wording is preserved. Translation is an interpretation of meaning. A wording search in one translation cannot establish whether a broader idea occurs in the Quran.</p><p>Where linked, Al-Tafsir al-Muyassar is the King Fahd Quran Printing Complex committee’s concise Arabic commentary, retrieved through <code>fetch_tafsir</code> for source checking. Full commentary is not redistributed.</p><p>Topic groupings, related links, questions, and reading titles are editorial learning aids. They are not exhaustive classifications, scholarly rulings, or statements made by the source provider. The prophets library presents selected Quran passages rather than complete biographies; its alphabetical order does not assert chronology. The calculator models user-supplied study estimates and makes no prediction about learning ability.</p><h2>Snapshot and reuse</h2><p>Retrieved {provenance.retrievedAt.slice(0,10)}. Arabic and English came from <code>fetch_quran</code> and <code>fetch_translation</code>; chapter counts and the 604-page Hafs layout came from Quran MCP structural metadata. Other printed layouts have different pagination.</p><p class="micro">Snapshot SHA-256: <code style="overflow-wrap:anywhere">{provenance.snapshotSha256}</code></p><p>Original application code is MIT licensed. DM Sans, Newsreader, and Amiri are hosted locally with their SIL Open Font Licenses. No personal blogs are used.</p><h2>References</h2><ul class="source-list">{sources.map(s=><li><a href={s.url} target="_blank" rel="noopener noreferrer">{s.label} ↗</a><small>{s.kind}</small></li>)}</ul><button class="button secondary" data-print>Print source notes</button></article></Shell>
''',encoding='utf-8')
 (app/'README.md').write_text(f'''# {name}\n\n{description}\n\nIndependent Astro 7 static app. Bun 1.4.4 is the build/runtime tool.\n\n```sh\nbun install --frozen-lockfile\nbun run dev\nbun run check\nbun test\nbun run build\n```\n\nDevelopment: port {4326+i}. Cloudflare Pages root: `apps/{slug}`; build: `bun run build`; output: `dist`. Set `BUN_VERSION=1.4.4`. No environment secrets, adapters, Functions, databases, or accounts. For direct upload use the corresponding ZIP in the repository release directory.\n\nContent and source provenance live in `src/data`. Canonical text was fetched through the official Quran MCP at https://mcp.quran.ai. See the in-app Sources page for editions and editorial limits. Optional browser data expires on access after 30 days and can be cleared through the footer.\n''',encoding='utf-8')
 print(slug)
